namespace ms {

static const char* kHeaderText = R"MSHDR(/* ==========================================================================
 * @@HEADER@@
 * Migration log helpers - generated by CopyMigration Switcher
 *
 * INPUT_LOG(...)  - function entry
 * OUTPUT_LOG(...) - function exit (return value)
 * TEMP_LOG(...)   - any other trace
 *
 * Logging is ON by default. It can be switched off at runtime with
 *     ms_log_set_enabled(0);
 * or before startup with the environment variable MS_LOG_ENABLED=0.
 * While disabled each macro only reads one volatile flag.
 * Output is CSV: timestamp,kind,function,file,line,message
 * This file is ASCII only, so it compiles with any source charset.
 * ========================================================================== */
#ifndef MS_MIGRATION_LOG_H
#define MS_MIGRATION_LOG_H

#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

#define MS_LOG_KIND_INPUT   1
#define MS_LOG_KIND_OUTPUT  2
#define MS_LOG_KIND_TEMP    3

int  ms_log_init(const char* path);
void ms_log_shutdown(void);
void ms_log_flush(void);
void ms_log_set_enabled(int enabled);
int  ms_log_is_enabled(void);
const char* ms_log_path(void);
void ms_log_write(int kind, const char* function, const char* file, int line,
                  const char* fmt, ...);
unsigned long long ms_log_count(int kind);
void               ms_log_reset_count(void);
const char* ms_log_kind_name(int kind);

#ifdef __cplusplus
}
#endif

#if defined(_MSC_VER)
#  define MS_LOG_FUNC __FUNCTION__
#elif defined(__STDC_VERSION__) && (__STDC_VERSION__ >= 199901L)
#  define MS_LOG_FUNC __func__
#else
#  define MS_LOG_FUNC __FUNCTION__
#endif

#define INPUT_LOG(...)                                                    \
    do {                                                                  \
        if (ms_log_is_enabled())                                          \
            ms_log_write(MS_LOG_KIND_INPUT, MS_LOG_FUNC, __FILE__,        \
                         __LINE__, __VA_ARGS__);                          \
    } while (0)

#define OUTPUT_LOG(...)                                                   \
    do {                                                                  \
        if (ms_log_is_enabled())                                          \
            ms_log_write(MS_LOG_KIND_OUTPUT, MS_LOG_FUNC, __FILE__,       \
                         __LINE__, __VA_ARGS__);                          \
    } while (0)

#define TEMP_LOG(...)                                                     \
    do {                                                                  \
        if (ms_log_is_enabled())                                          \
            ms_log_write(MS_LOG_KIND_TEMP, MS_LOG_FUNC, __FILE__,         \
                         __LINE__, __VA_ARGS__);                          \
    } while (0)

#endif /* MS_MIGRATION_LOG_H */
)MSHDR";
static const char* kSourceText = R"MSSRC(/* ==========================================================================
 * @@SOURCE@@
 * Implementation of @@HEADER@@ - generated by CopyMigration Switcher
 * This file is ASCII only.
 * ========================================================================== */
#define _CRT_SECURE_NO_WARNINGS

/* The header is normally on the include path. If it is not (this file was
   copied without the header), the declarations below keep this translation
   unit compilable on its own. */
#if defined(__has_include)
#  if __has_include("@@HEADER@@")
#    include "@@HEADER@@"
#    define MS_LOG_HAVE_HEADER 1
#  endif
#endif

#ifndef MS_LOG_KIND_INPUT
#  define MS_LOG_KIND_INPUT   1
#endif
#ifndef MS_LOG_KIND_OUTPUT
#  define MS_LOG_KIND_OUTPUT  2
#endif
#ifndef MS_LOG_KIND_TEMP
#  define MS_LOG_KIND_TEMP    3
#endif

#include <stdio.h>
#include <stdarg.h>
#include <string.h>
#include <time.h>
#include <stdlib.h>

#ifdef _WIN32
#  include <windows.h>
#else
#  include <pthread.h>
#  include <sys/time.h>
#  include <unistd.h>
#endif

#ifdef __cplusplus
#  define MS_LOG_LINKAGE extern "C"
extern "C" {
#else
#  define MS_LOG_LINKAGE
#endif

MS_LOG_LINKAGE int  ms_log_init(const char* path);
MS_LOG_LINKAGE void ms_log_shutdown(void);
MS_LOG_LINKAGE void ms_log_flush(void);
MS_LOG_LINKAGE void ms_log_set_enabled(int enabled);
MS_LOG_LINKAGE int  ms_log_is_enabled(void);
MS_LOG_LINKAGE const char* ms_log_path(void);
MS_LOG_LINKAGE void ms_log_write(int kind, const char* function, const char* file,
                                 int line, const char* fmt, ...);
MS_LOG_LINKAGE unsigned long long ms_log_count(int kind);
MS_LOG_LINKAGE void ms_log_reset_count(void);
MS_LOG_LINKAGE const char* ms_log_kind_name(int kind);

#ifdef __cplusplus
}
#endif

static volatile long g_enabled = @@DEF_ENABLED@@;
static FILE*         g_file = NULL;
static char          g_path[1024] = { 0 };
static char          g_buf[65536];
static size_t        g_len = 0;
static unsigned long long g_count[4] = { 0, 0, 0, 0 };
static unsigned long g_lines = 0;
static unsigned long g_dropped = 0;
static int           g_initialized = 0;

#ifndef MS_LOG_FLUSH_LINES
#  define MS_LOG_FLUSH_LINES 200
#endif

#ifdef _WIN32
static CRITICAL_SECTION g_cs;
static volatile LONG    g_cs_state = 0;

static void ms_log_lock_init(void)
{
    LONG s = InterlockedCompareExchange(&g_cs_state, 1, 0);
    if (s == 0) {
        InitializeCriticalSection(&g_cs);
        InterlockedExchange(&g_cs_state, 2);
    } else {
        while (InterlockedCompareExchange(&g_cs_state, 2, 2) != 2) Sleep(0);
    }
}
#  define MS_LOCK()         ms_log_lock_init(); EnterCriticalSection(&g_cs)
#  define MS_UNLOCK()       LeaveCriticalSection(&g_cs)
#  define MS_ATOMIC_INC(p)  InterlockedIncrement64((volatile LONG64*)(p))
#  define MS_ATOMIC_ZERO(p) InterlockedExchange64((volatile LONG64*)(p), 0)
#else
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
#  define MS_LOCK()         pthread_mutex_lock(&g_mutex)
#  define MS_UNLOCK()       pthread_mutex_unlock(&g_mutex)
#  define MS_ATOMIC_INC(p)  (++(*(p)))
#  define MS_ATOMIC_ZERO(p) ((*(p)) = 0)
#endif

static void ms_log_timestamp(char* out, size_t cap)
{
#ifdef _WIN32
    SYSTEMTIME st;
    GetLocalTime(&st);
    _snprintf(out, cap, "%04d-%02d-%02d %02d:%02d:%02d.%03d",
              (int)st.wYear, (int)st.wMonth, (int)st.wDay,
              (int)st.wHour, (int)st.wMinute, (int)st.wSecond,
              (int)st.wMilliseconds);
#else
    struct timeval tv;
    struct tm tmv;
    gettimeofday(&tv, NULL);
    localtime_r(&tv.tv_sec, &tmv);
    snprintf(out, cap, "%04d-%02d-%02d %02d:%02d:%02d.%03d",
             tmv.tm_year + 1900, tmv.tm_mon + 1, tmv.tm_mday,
             tmv.tm_hour, tmv.tm_min, tmv.tm_sec, (int)(tv.tv_usec / 1000));
#endif
    if (cap > 0) out[cap - 1] = '\0';
}

static void ms_log_put_csv(char* dst, size_t cap, size_t* pos, const char* s)
{
    size_t p = *pos;
    if (p + 1 >= cap) return;
    dst[p++] = '"';
    if (s) {
        for (; *s && p + 2 < cap; ++s) {
            if (*s == '"') dst[p++] = '"';
            dst[p++] = *s;
        }
    }
    if (p + 1 < cap) dst[p++] = '"';
    *pos = p;
}

static void ms_log_flush_locked(void)
{
    if (g_len == 0) return;
    if (g_file) {
        fwrite(g_buf, 1, g_len, g_file);
        fflush(g_file);
    }
    g_len = 0;
}

MS_LOG_LINKAGE const char* ms_log_kind_name(int kind)
{
    switch (kind) {
    case MS_LOG_KIND_INPUT:  return "INPUT";
    case MS_LOG_KIND_OUTPUT: return "OUTPUT";
    case MS_LOG_KIND_TEMP:   return "TEMP";
    default:                 return "OTHER";
    }
}

MS_LOG_LINKAGE int ms_log_init(const char* path)
{
    char def[1024];
    const char* target = path;

    if (!target || !*target) {
#ifdef _WIN32
        char exe[1024];
        DWORD n = GetModuleFileNameA(NULL, exe, (DWORD)sizeof(exe));
        if (n > 0) {
            char* p = strrchr(exe, '\\');
            if (p) *(p + 1) = '\0';
            _snprintf(def, sizeof(def), "%sms_migration_log.csv", exe);
        } else {
            _snprintf(def, sizeof(def), "ms_migration_log.csv");
        }
#else
        snprintf(def, sizeof(def), "ms_migration_log.csv");
#endif
        def[sizeof(def) - 1] = '\0';
        target = def;
    }

    MS_LOCK();
    if (g_file) { fclose(g_file); g_file = NULL; }
    strncpy(g_path, target, sizeof(g_path) - 1);
    g_path[sizeof(g_path) - 1] = '\0';
    g_file = fopen(target, "ab");
    g_len = 0;
    g_lines = 0;
    g_initialized = 1;
    if (!g_file) {
        ++g_dropped;
        MS_UNLOCK();
        return -1;
    }
    {
        long pos = ftell(g_file);
        if (pos == 0) {
            fputs("timestamp,kind,function,file,line,message\r\n", g_file);
            fflush(g_file);
        }
    }
    MS_UNLOCK();

    {
        const char* e = getenv("MS_LOG_ENABLED");
        if (e && *e == '0') ms_log_set_enabled(0);
    }
    return 0;
}

MS_LOG_LINKAGE void ms_log_shutdown(void)
{
    MS_LOCK();
    ms_log_flush_locked();
    if (g_file) { fclose(g_file); g_file = NULL; }
    g_initialized = 0;
    MS_UNLOCK();
}

MS_LOG_LINKAGE void ms_log_flush(void)
{
    MS_LOCK();
    ms_log_flush_locked();
    MS_UNLOCK();
}

MS_LOG_LINKAGE void ms_log_set_enabled(int enabled)
{
#ifdef _WIN32
    InterlockedExchange(&g_enabled, enabled ? 1 : 0);
#else
    g_enabled = enabled ? 1 : 0;
#endif
}

MS_LOG_LINKAGE int ms_log_is_enabled(void)
{
    return g_enabled != 0;
}

MS_LOG_LINKAGE const char* ms_log_path(void)
{
    return g_path;
}

MS_LOG_LINKAGE void ms_log_write(int kind, const char* function, const char* file,
                                 int line, const char* fmt, ...)
{
    char msg[2048];
    char ts[40];
    size_t pos = 0;
    va_list ap;

    if (!g_enabled) return;

    msg[0] = '\0';
    if (fmt) {
        va_start(ap, fmt);
        vsnprintf(msg, sizeof(msg), fmt, ap);
        va_end(ap);
        msg[sizeof(msg) - 1] = '\0';
    }

    ms_log_timestamp(ts, sizeof(ts));

    MS_LOCK();
    if (!g_file) { MS_UNLOCK(); return; }
    pos = g_len;
    if (pos + 64 < sizeof(g_buf)) {
        int n = _snprintf(g_buf + pos, sizeof(g_buf) - pos, "%s,", ts);
        if (n > 0) pos += (size_t)n;
    }
    ms_log_put_csv(g_buf, sizeof(g_buf), &pos, ms_log_kind_name(kind));
    if (pos + 2 < sizeof(g_buf)) g_buf[pos++] = ',';
    ms_log_put_csv(g_buf, sizeof(g_buf), &pos, function ? function : "");
    if (pos + 2 < sizeof(g_buf)) g_buf[pos++] = ',';
    ms_log_put_csv(g_buf, sizeof(g_buf), &pos, file ? file : "");
    if (pos + 24 < sizeof(g_buf)) {
        int n = _snprintf(g_buf + pos, sizeof(g_buf) - pos, ",%d,", line);
        if (n > 0) pos += (size_t)n;
    }
    ms_log_put_csv(g_buf, sizeof(g_buf), &pos, msg);
    if (pos + 2 < sizeof(g_buf)) { g_buf[pos++] = '\r'; g_buf[pos++] = '\n'; }
    g_len = pos;

    MS_ATOMIC_INC(&g_count[(kind >= 1 && kind <= 3) ? kind : 0]);
    ++g_lines;
    if (g_lines >= (unsigned long)MS_LOG_FLUSH_LINES || g_len > sizeof(g_buf) - 4096) {
        ms_log_flush_locked();
        g_lines = 0;
    }
    MS_UNLOCK();
}

MS_LOG_LINKAGE unsigned long long ms_log_count(int kind)
{
    if (kind < 1 || kind > 3) return 0;
    return (unsigned long long)g_count[kind];
}

MS_LOG_LINKAGE void ms_log_reset_count(void)
{
    MS_ATOMIC_ZERO(&g_count[1]);
    MS_ATOMIC_ZERO(&g_count[2]);
    MS_ATOMIC_ZERO(&g_count[3]);
}

#if defined(_MSC_VER)
static void __cdecl ms_log_atexit(void) { ms_log_shutdown(); }
#else
__attribute__((destructor)) static void ms_log_atexit(void) { ms_log_shutdown(); }
#endif
)MSSRC";

static std::string ExpandNames(const std::string& src, const LogRuntimeOptions& opt,
                               bool def_enabled)
{
    std::string s = src;
    std::string h = util::WideToUtf8(opt.header_name);
    std::wstring srcname = opt.source_is_cpp ? L"ms_migration_log.cpp" : L"ms_migration_log.c";
    std::string sn = util::WideToUtf8(srcname);
    std::string out;
    out.reserve(s.size());
    for (size_t i = 0; i < s.size(); ) {
        if (s.compare(i, 2, "@@") == 0) {
            size_t e = s.find("@@", i + 2);
            if (e != std::string::npos) {
                std::string key = s.substr(i + 2, e - i - 2);
                if (key == "HEADER") out += h;
                else if (key == "SOURCE") out += sn;
                else if (key == "DEF_ENABLED") out += (def_enabled ? "1" : "0");
                else out += s.substr(i, e - i + 2);
                i = e + 2;
                continue;
            }
        }
        out.push_back(s[i++]);
    }
    return out;
}

std::string LogRuntimeGenerator::HeaderText(const LogRuntimeOptions& opt)
{
    return ExpandNames(kHeaderText, opt, opt.default_enabled);
}

std::string LogRuntimeGenerator::SourceText(const LogRuntimeOptions& opt)
{
    return ExpandNames(kSourceText, opt, opt.default_enabled);
}

bool LogRuntimeGenerator::WriteTo(const std::wstring& dir,
                                  const LogRuntimeOptions& opt,
                                  std::vector<std::wstring>& out_files,
                                  std::wstring& out_error)
{
    out_error.clear();
    out_files.clear();
    if (dir.empty()) { out_error = L"出力先が空です。"; return false; }
    if (!util::EnsureDirectory(dir)) {
        out_error = L"出力先を作成できません: " + dir;
        return false;
    }

    std::wstring src_name = opt.source_is_cpp ? L"ms_migration_log.cpp" : L"ms_migration_log.c";
    std::wstring hp = util::JoinPath(dir, opt.header_name);
    std::wstring sp = util::JoinPath(dir, src_name);

    std::string h = HeaderText(opt);
    std::string s = SourceText(opt);

    std::wstring werr;
    if (!FileManager::WriteTextAtomic(hp, util::Utf8ToWide(h), TextEncoding::UTF8, false,
                                      NewlineKind::CRLF, werr)) {
        out_error = L"ヘッダを書き出せません: " + werr;
        return false;
    }
    out_files.push_back(hp);

    if (opt.include_source) {
        if (!FileManager::WriteTextAtomic(sp, util::Utf8ToWide(s), TextEncoding::UTF8, false,
                                          NewlineKind::CRLF, werr)) {
            out_error = L"実装を書き出せません: " + werr;
            return false;
        }
        out_files.push_back(sp);
    }
    return true;
}

std::wstring LogRuntimeGenerator::UsageText()
{
    std::wstring t;
    t += L"# Log runtime usage\r\n\r\n";
    t += L"1. Add ms_migration_log.h and ms_migration_log.c (or .cpp) to the project.\r\n\r\n";
    t += L"2. Initialize (optional):\r\n";
    t += L"     ms_log_init(\"migration_log.csv\");\r\n";
    t += L"     ms_log_set_enabled(1);\r\n";
    t += L"     ms_log_shutdown();\r\n\r\n";
    t += L"3. Macros:\r\n";
    t += L"     INPUT_LOG(\"item=%d\", item);   /* function entry */\r\n";
    t += L"     OUTPUT_LOG(\"rc=%d\", rc);      /* function exit  */\r\n";
    t += L"     TEMP_LOG(\"trace\");           /* any trace      */\r\n\r\n";
    t += L"4. Load test: while disabled the cost is one volatile read.\r\n";
    t += L"   MS_LOG_ENABLED=0 disables it from startup.\r\n";
    return t;
}

} // namespace ms
